import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:http/http.dart' as http;import '../config.dart';
class AdminHome extends StatefulWidget{const AdminHome({super.key});@override State<AdminHome> createState()=>_AdminHomeState();}
class _AdminHomeState extends State<AdminHome>{final store=const FlutterSecureStorage();final username=TextEditingController(text:'admin'),password=TextEditingController();String? token;List<dynamic> rows=[];bool loading=false;
Future<void> login()async{try{final r=await http.post(Uri.parse('${AppConfig.apiBaseUrl}/api/admin/login'),headers:{'Content-Type':'application/json'},body:jsonEncode({'username':username.text,'password':password.text}));if(r.statusCode!=200)throw Exception('ورود ناموفق');token=jsonDecode(r.body)['access_token'];await store.write(key:'admin_token',value:token);password.clear();await list();}catch(e){msg('$e');}}
Future<void> restore()async{token=await store.read(key:'admin_token');if(token!=null)list();}
@override void initState(){super.initState();restore();}
Future<void> list()async{setState(()=>loading=true);try{final r=await http.get(Uri.parse('${AppConfig.apiBaseUrl}/api/admin/servers'),headers:{'Authorization':'Bearer $token'});if(r.statusCode==401){token=null;await store.delete(key:'admin_token');}else if(r.statusCode==200)rows=jsonDecode(r.body);}catch(e){msg('خطا: $e');}finally{if(mounted)setState(()=>loading=false);}}
void msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
Future<void> edit([Map<String,dynamic>? item])async{final n=TextEditingController(text:item?['name']??''),c=TextEditingController(text:item?['config']??''),d=TextEditingController(text:item?['description']??'');bool active=item?['active']??true;final key=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,sd)=>AlertDialog(title:Text(item==null?'افزودن سرور':'ویرایش سرور'),content:SizedBox(width:480,child:Form(key:key,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:n,decoration:const InputDecoration(labelText:'نام سرور'),validator:(v)=>v==null||v.trim().isEmpty?'نام لازم است':null),TextFormField(controller:c,minLines:2,maxLines:5,decoration:const InputDecoration(labelText:'کانفیگ (لینک یا JSON)'),validator:(v)=>v==null||v.trim().isEmpty?'کانفیگ لازم است':null),TextFormField(controller:d,decoration:const InputDecoration(labelText:'توضیحات')),SwitchListTile(value:active,onChanged:(v)=>sd(()=>active=v),title:const Text('فعال'))])))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('لغو')),FilledButton(onPressed:()=>key.currentState!.validate()?Navigator.pop(ctx,true):null,child:const Text('ذخیره'))]));if(ok!=true)return;final body=jsonEncode({'name':n.text.trim(),'config':c.text.trim(),'description':d.text.trim().isEmpty?null:d.text.trim(),'active':active,'sort_order':item?['sort_order']??0});final url=Uri.parse('${AppConfig.apiBaseUrl}/api/admin/servers'+(item==null?'':'/'+item['id'].toString()));final headers={'Authorization':'Bearer $token','Content-Type':'application/json'};final r=item==null?await http.post(url,headers:headers,body:body):await http.put(url,headers:headers,body:body);if(r.statusCode<300)await list();else msg('ذخیره نشد: ${r.body}');}
Future<void> remove(Map<String,dynamic> x)async{final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('حذف سرور؟'),content:Text(x['name']),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('خیر')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حذف'))]));if(yes!=true)return;final r=await http.delete(Uri.parse('${AppConfig.apiBaseUrl}/api/admin/servers/${x['id']}'),headers:{'Authorization':'Bearer $token'});if(r.statusCode==204)list();else msg('حذف ناموفق');}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('MahdiVPN Admin'),actions:[if(token!=null)IconButton(onPressed:()=>edit(),icon:const Icon(Icons.add))]),body:token==null?Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[TextField(controller:username,decoration:const InputDecoration(labelText:'نام مدیر')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'رمز عبور')),const SizedBox(height:18),FilledButton(onPressed:login,child:const Text('ورود مدیر'))])):loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:list,child:ListView(children:rows.map<Widget>((e)=>ListTile(title:Text(e['name']),subtitle:Text(e['active']?'فعال':'غیرفعال'),trailing:Wrap(children:[IconButton(onPressed:()=>edit(Map<String,dynamic>.from(e)),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(Map<String,dynamic>.from(e)),icon:const Icon(Icons.delete))]))).toList())));}
